// Scalar analysis for the PyYAML-compatible emitter.
// Port of PyYAML's Emitter.analyze_scalar (lib/yaml/emitter.py) with
// allow_unicode=False, which is what yaml.dump() uses by default.
//
// All lengths and indices are in Unicode code points (like Python strings),
// so the input is split with Array.from() before inspection.

// Characters PyYAML treats as whitespace when deciding whether an indicator
// is "preceded/followed by whitespace".
const WHITESPACE = '\x00 \t\r\n\x85\u2028\u2029';

export class ScalarAnalysis {
  constructor(scalar, chars, flags) {
    this.scalar = scalar;            // original string
    this.chars = chars;              // array of code points
    this.empty = flags.empty;
    this.multiline = flags.multiline;
    this.allowFlowPlain = flags.allowFlowPlain;
    this.allowBlockPlain = flags.allowBlockPlain;
    this.allowSingleQuoted = flags.allowSingleQuoted;
    this.allowDoubleQuoted = flags.allowDoubleQuoted;
    this.allowBlock = flags.allowBlock;
  }
}

export function analyzeScalar(scalar) {
  const chars = Array.from(scalar);

  // Empty scalar is a special case.
  if (chars.length === 0) {
    return new ScalarAnalysis(scalar, chars, {
      empty: true, multiline: false,
      allowFlowPlain: false, allowBlockPlain: true,
      allowSingleQuoted: true, allowDoubleQuoted: true,
      allowBlock: false,
    });
  }

  // Indicators and special characters.
  let blockIndicators = false;
  let flowIndicators = false;
  let lineBreaks = false;
  let specialCharacters = false;

  // Important whitespace combinations.
  let leadingSpace = false;
  let leadingBreak = false;
  let trailingSpace = false;
  let trailingBreak = false;
  let breakSpace = false;
  let spaceBreak = false;

  // Check document indicators.
  if (scalar.startsWith('---') || scalar.startsWith('...')) {
    blockIndicators = true;
    flowIndicators = true;
  }

  // Preceded by whitespace is the same as followed by whitespace for the
  // first character.
  let precededByWhitespace = true;
  let followedByWhitespace = (chars.length === 1
      || WHITESPACE.includes(chars[1]));

  let checkIndicators = true;
  let previousSpace = false;
  let previousBreak = false;

  for (let index = 0; index < chars.length; index++) {
    const ch = chars[index];

    // Check for indicators.
    if (checkIndicators) {
      // Leading indicators are special characters.
      if ('#,[]{}&*!|>\'"%@`'.includes(ch)) {
        flowIndicators = true;
        blockIndicators = true;
      }
      if ('?:'.includes(ch)) {
        flowIndicators = true;
        if (followedByWhitespace) {
          blockIndicators = true;
        }
      }
      if (ch === '-' && followedByWhitespace) {
        flowIndicators = true;
        blockIndicators = true;
      }
    } else {
      // Some indicators cannot appear within a scalar as well.
      if (',?[]{}'.includes(ch)) {
        flowIndicators = true;
      }
      if (ch === ':') {
        flowIndicators = true;
        if (followedByWhitespace) {
          blockIndicators = true;
        }
      }
      if (ch === '#' && precededByWhitespace) {
        flowIndicators = true;
        blockIndicators = true;
      }
    }

    // Check for line breaks, special, and unicode characters.
    if (ch === '\n' || ch === '\x85') {
      lineBreaks = true;
    }
    const cp = ch.codePointAt(0);
    if (!(ch === '\n' || (cp >= 0x20 && cp <= 0x7E))) {
      // With allow_unicode=False every non-ASCII-printable character makes
      // the scalar "special" (forces double-quoted style).
      specialCharacters = true;
    }

    // Detect important whitespace combinations.
    if (ch === ' ') {
      if (index === 0) {
        leadingSpace = true;
      }
      if (index === chars.length - 1) {
        trailingSpace = true;
      }
      if (previousBreak) {
        breakSpace = true;
      }
      previousSpace = true;
      previousBreak = false;
    } else if (ch === '\n' || ch === '\x85') {
      if (index === 0) {
        leadingBreak = true;
      }
      if (index === chars.length - 1) {
        trailingBreak = true;
      }
      if (previousSpace) {
        spaceBreak = true;
      }
      previousSpace = false;
      previousBreak = true;
    } else {
      previousSpace = false;
      previousBreak = false;
    }

    // Prepare for the next character.
    checkIndicators = false;
    precededByWhitespace = WHITESPACE.includes(ch);
    followedByWhitespace = (index + 1 >= chars.length
        || WHITESPACE.includes(chars[index + 1]));
  }

  // Let's decide what styles are allowed.
  let allowFlowPlain = true;
  let allowBlockPlain = true;
  let allowSingleQuoted = true;
  let allowDoubleQuoted = true;
  let allowBlock = true;

  // Leading and trailing whitespaces are bad for plain scalars.
  if (leadingSpace || leadingBreak || trailingSpace || trailingBreak) {
    allowFlowPlain = false;
    allowBlockPlain = false;
  }

  // We do not permit trailing spaces for block scalars.
  if (trailingSpace) {
    allowBlock = false;
  }

  // Spaces at the beginning of a new line are only acceptable for block
  // scalars.
  if (breakSpace) {
    allowFlowPlain = false;
    allowBlockPlain = false;
    allowSingleQuoted = false;
  }

  // Spaces followed by breaks, as well as special characters are only
  // allowed for double quoted scalars.
  if (spaceBreak || specialCharacters) {
    allowFlowPlain = false;
    allowBlockPlain = false;
    allowSingleQuoted = false;
    allowBlock = false;
  }

  // Although the plain scalar writer supports breaks, we never emit
  // multiline plain scalars.
  if (lineBreaks) {
    allowFlowPlain = false;
    allowBlockPlain = false;
  }

  // Flow indicators are forbidden for flow plain scalars.
  if (flowIndicators) {
    allowFlowPlain = false;
  }

  // Block indicators are forbidden for block plain scalars.
  if (blockIndicators) {
    allowBlockPlain = false;
  }

  return new ScalarAnalysis(scalar, chars, {
    empty: false, multiline: lineBreaks,
    allowFlowPlain, allowBlockPlain,
    allowSingleQuoted, allowDoubleQuoted,
    allowBlock,
  });
}
